ALTER TABLE "meal_entries" ADD CONSTRAINT "meal_entries_nutrition_finite_check" CHECK ("meal_entries"."calories_kcal_per_serving" NOT IN ('NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision) AND "meal_entries"."protein_g_per_serving" NOT IN ('NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision) AND "meal_entries"."carbs_g_per_serving" NOT IN ('NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision) AND "meal_entries"."fat_g_per_serving" NOT IN ('NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision) AND "meal_entries"."fiber_g_per_serving" NOT IN ('NaN'::double precision, 'Infinity'::double precision, '-Infinity'::double precision));